/*
 * Tratamiento de excepciones
 */
void Exception( CORBA_Environment *ev)
{
  switch (ev->_major)
    {
    case CORBA_NO_EXCEPTION: return;
    case CORBA_SYSTEM_EXCEPTION:
      g_printerr ("CORBA system exception.\n");
      exit (1);
    case CORBA_USER_EXCEPTION:
      g_printerr (CORBA_exception_id(ev));
      exit(1);
    default :
      g_printerr ("Unknown value for major exception !!!\n");
      exit(1);
    }
}

int
main(int argc, char* argv[])
{
  CORBA_ORB orb = NULL;
  PortableServer_POA poa;
  CORBA_Environment ev;
  CosEventChannelAdmin_EventChannel channel;
  CosEventChannelAdmin_SupplierAdmin supplier_admin;
  CosEventChannelAdmin_ProxyPushConsumer consumer;
  CosEventComm_PushSupplier self_push_supplier;
  CORBA_any *message = CORBA_any_alloc();
  static CORBA_char *svalue = "Hola mundo";
  char *ior;
  
  
  CORBA_exception_init(&ev);
  orb = CORBA_ORB_init(&argc, argv, "orbit-local-orb", &ev);
  poa = (PortableServer_POA)CORBA_ORB_resolve_initial_references(orb, "RootPOA", &ev);
  PortableServer_POAManager_activate(PortableServer_POA__get_the_POAManager(poa, &ev), &ev);

  if(argc < 2) {
	 printf("Necesito el IOR del canal de eventos como argv[1]\n");
	 return 1;
  }
  
  /* Instaciamos el Canal de eventos  */
  channel = CORBA_ORB_string_to_object(orb, argv[1], &ev);
  Exception (&ev);
  if (CORBA_Object_is_nil(channel, &ev)) {
	 printf("No puedo conectar con %s\n", argv[1]);
	 return 1;
  }
  
  /* Creamos nuestro push_supplier */
  self_push_supplier = impl_CosEventComm_PushSupplier__create(poa, &ev);
  Exception (&ev);
  if (CORBA_Object_is_nil(self_push_supplier, &ev)) {
	 printf("Error creando el push_supplier:\n");
	 return 1;
  }

  /* Obtenemos el SupplierAdmin */
  supplier_admin = CosEventChannelAdmin_EventChannel_for_suppliers(channel, &ev);
  Exception (&ev);
  if (CORBA_Object_is_nil(supplier_admin, &ev)) {
	 printf("Error obteniendo el supplier_admin:\n");
	 return 1;
  }
  
  /* Obtenemos el ProxyPushConsumer */
  consumer = CosEventChannelAdmin_SupplierAdmin_obtain_push_consumer (supplier_admin, &ev);
  Exception (&ev);
  if (CORBA_Object_is_nil(consumer, &ev)) {
	 printf("Error obteniendo el ProxyPushConsumer del canal:\n");
	 return 1;
  }
  
  
  /* Conectamos el push_consumer al ProxyPushConsumer */
  CosEventChannelAdmin_ProxyPushConsumer_connect_push_supplier(consumer, CORBA_OBJECT_NIL, &ev);
  Exception (&ev);
  /* Enviamos el evento */
  message->_type = TC_CORBA_string;
  message->_value = &svalue;

  CORBA_any_set_release(message, CORBA_FALSE);
 
  printf ("Evento enviado\n");
  printf("\n");
  
  CosEventChannelAdmin_ProxyPushConsumer_push(consumer, message, &ev);  
  Exception (&ev);
 
  
}

